-- 플래그/퀘스트 연결은
-- 수정하지 않으며, 공식 l10n 보정 API를 통해 이름(1)과 직책(14)만 등록합니다.
-- OpenMap과 Questie는 동일한 QueryNPCSingle 경로에서 번역을 받습니다.
-- OnUpdate, 지도 이동/확대 콜백, 타이머, 별도 버튼을 추가하지 않습니다.
-- SetCorrection은 입력을 복사하고 캐시를 무효화하므로 이미 읽은 영어도
-- 재사용되지 않습니다. 아래 임시 테이블은 등록이 끝나면 회수할 수 있습니다.
